    result={'at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'independent-saved-hand-clip-audit-complete','checks':checks,'technical_scope_pass':all(checks.values()),'source_sha256':source_hash,'candidate_sha256':candidate_hash,'profile_sha256':sha(a.profile),'motion_sha256':sha(a.motion),'writer_sha256':sha(Path(__file__)),'runtime_sha256':sha(Path(__file__).with_name('hand_control_runtime.py')),'binding_sha256':binding,'skin_geometry_signature':identity,'motion_frames':plan['frames'],'sampling_window':window,'covers_complete_motion':window==plan['frames'],'sampling_module_sha256':sha(Path(__file__).with_name('hand_audit_sampling.py')),'sample_count':len(times),'integer_sample_count':len(times)-subframe_count,'subframe_sample_count':subframe_count,'requested_sampling_checks_pass':all(v is True for v in checks.values() if v is not None),'unexecuted_checks':[k for k,v in checks.items() if v is None],'substeps':a.substeps,'max_subframe_error_degrees':a.max_subframe_error_degrees,'errors':errors,'maximum_evaluated_skin_difference_world':max_movement,'boundary_skin_comparison':boundaries,'protected_bone_count':len(protected),'allowed_bones_exact':sorted(allowed),'attached_objects_exact':attached,'snapshot_file':str(snapshots),'snapshot_sha256':sha(snapshots),'rows':rows,'normal_speed_continuous_viewing':False,'scope':'Only the declared sampling window is audited; separate windows require verified coverage before a whole-motion claim. Selected original hand/wrist-weighted triangle pairs (shared vertices excluded); finite evaluated skin, actual nonfinger vertices, nonselected bone/object worlds, local translation/scale, morphs and rest geometry protected. No full closed-volume, unselected-region self-collision, prop grip/friction, anatomical or continuous naturalness certification. Exit0 means inspection completed: read all check booleans.'};report.parent.mkdir(parents=True,exist_ok=True);report.write_text(json.dumps(result,ensure_ascii=False,indent=2),'utf-8');print('HAND_AUDIT_DONE',json.dumps({'checks':checks,'errors':errors}),flush=True)
